import{_ as s,c as a,o as i,ag as t}from"./chunks/framework.Vyheyqg9.js";const u=JSON.parse('{"title":"What if we are facing performance issues because we have lots of requests?","description":"","frontmatter":{},"headers":[],"relativePath":"senior_growth/Web_Performance/What_if_we_are_facing_performance_issues_because_we_have_lots_of_requests.md","filePath":"senior_growth/Web_Performance/What_if_we_are_facing_performance_issues_because_we_have_lots_of_requests.md"}'),r={name:"senior_growth/Web_Performance/What_if_we_are_facing_performance_issues_because_we_have_lots_of_requests.md"};function n(l,e,o,h,d,c){return i(),a("div",null,[...e[0]||(e[0]=[t(`<h1 id="what-if-we-are-facing-performance-issues-because-we-have-lots-of-requests" tabindex="-1">What if we are facing performance issues because we have lots of requests? <a class="header-anchor" href="#what-if-we-are-facing-performance-issues-because-we-have-lots-of-requests" aria-label="Permalink to “What if we are facing performance issues because we have lots of requests?”">​</a></h1><h2 id="handling-performance-issues-caused-by-too-many-requests" tabindex="-1"><span class="hub-section-number">1 </span>Handling Performance Issues Caused by Too Many Requests <a class="header-anchor" href="#handling-performance-issues-caused-by-too-many-requests" aria-label="Permalink to “1 Handling Performance Issues Caused by Too Many Requests”">​</a></h2><p>When your app makes <strong>lots of HTTP requests</strong>, it can slow down <strong>initial load</strong>, hurt <strong>runtime performance</strong>, and strain your <strong>server</strong>.<br> Requests consume bandwidth/server/scheduling capacity, but do not each require a new DNS/TCP/TLS setup. Reuse, multiplexing, caches, dependencies and payload/processing cost determine impact.</p><hr><h2 id="⚠️-why-too-many-requests-are-a-problem" tabindex="-1"><span class="hub-section-number">2 </span>Why Too Many Requests Are a Problem <a class="header-anchor" href="#⚠️-why-too-many-requests-are-a-problem" aria-label="Permalink to “2 Why Too Many Requests Are a Problem”">​</a></h2><table tabindex="0"><thead><tr><th>Impact</th><th>Description</th></tr></thead><tbody><tr><td><strong>Increased Load Time</strong></td><td>New origins/connections can require setup; reused connections share setup across requests.</td></tr><tr><td><strong>Blocked Rendering</strong></td><td>CSS/JS requests can block the critical rendering path.</td></tr><tr><td><strong>Network Congestion</strong></td><td>HTTP/1.1 connection limits are browser-specific; HTTP/2 and3 multiplex streams with negotiated limits and shared transport/resource constraints.</td></tr><tr><td><strong>Server Load</strong></td><td>Backend must handle many small requests instead of fewer, optimized ones.</td></tr><tr><td><strong>Energy &amp; Bandwidth</strong></td><td>Especially bad for mobile or slow networks.</td></tr></tbody></table><hr><h2 id="🔍-step-1-diagnose-and-measure" tabindex="-1"><span class="hub-section-number">3 </span>Diagnose and Measure <a class="header-anchor" href="#🔍-step-1-diagnose-and-measure" aria-label="Permalink to “3 Diagnose and Measure”">​</a></h2><p>Use the <strong>Network tab in Chrome DevTools</strong> or <strong>WebPageTest</strong> to check:</p><ul><li>Total number of requests</li><li>Types of requests (JS, CSS, fonts, images, API)</li><li>Timing (DNS, waiting, download)</li><li>Unnecessary or duplicate requests</li></ul><p><strong>Helpful Tools:</strong></p><ul><li><strong>Lighthouse</strong> – “Reduce the impact of third-party code” &amp; “Reduce payloads” audits</li><li><strong>Webpack Bundle Analyzer / Vite bundle visualizer</strong></li><li><strong>DevTools → Coverage tab</strong> – find unused JS/CSS</li></ul><hr><h2 id="🧩-step-2-optimize-static-asset-requests" tabindex="-1"><span class="hub-section-number">4 </span>Optimize Static Asset Requests <a class="header-anchor" href="#🧩-step-2-optimize-static-asset-requests" aria-label="Permalink to “4 Optimize Static Asset Requests”">​</a></h2><h3 id="_1-bundle-and-minify" tabindex="-1"><span class="hub-section-number">4.1 </span>Bundle and Minify <a class="header-anchor" href="#_1-bundle-and-minify" aria-label="Permalink to “4.1 Bundle and Minify”">​</a></h3><ul><li>Combine small JS/CSS files into bigger bundles (but <strong>don’t make one huge bundle</strong>; code splitting is still important).</li><li>Use <strong>tree shaking</strong> to remove unused code.</li><li>Enable <strong>Gzip</strong> or <strong>Brotli compression</strong>.</li></ul><h3 id="_2-code-splitting" tabindex="-1"><span class="hub-section-number">4.2 </span>Code Splitting <a class="header-anchor" href="#_2-code-splitting" aria-label="Permalink to “4.2 Code Splitting”">​</a></h3><ul><li>Dynamically import only what’s needed:<div class="language-js"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> Chart</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> React.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">lazy</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(() </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&gt;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;./Chart&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">));</span></span></code></pre></div></li><li>Load non-critical components after first render.</li></ul><h3 id="_3-asset-caching" tabindex="-1"><span class="hub-section-number">4.3 </span>Asset Caching <a class="header-anchor" href="#_3-asset-caching" aria-label="Permalink to “4.3 Asset Caching”">​</a></h3><ul><li>Use long-term caching with HTTP headers:<div class="language-http"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Cache-Control</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> max-age=31536000, immutable</span></span></code></pre></div></li><li>Version assets with file hashes (e.g. <code>main.abc123.js</code>).</li></ul><h3 id="_4-preload-prefetch" tabindex="-1"><span class="hub-section-number">4.4 </span>Preload &amp; Prefetch <a class="header-anchor" href="#_4-preload-prefetch" aria-label="Permalink to “4.4 Preload &amp; Prefetch”">​</a></h3><ul><li>Use HTML resource hints:<div class="language-html"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">link</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> rel</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;stylesheet&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> href</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;critical.css&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">&lt;!-- Preload only if late discovery is proven; use as=&quot;style&quot; and still consume it. --&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">link</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> rel</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;prefetch&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> href</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;next-page.js&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div></li></ul><h3 id="_5-serve-through-a-cdn" tabindex="-1"><span class="hub-section-number">4.5 </span>Serve Through a CDN <a class="header-anchor" href="#_5-serve-through-a-cdn" aria-label="Permalink to “4.5 Serve Through a CDN”">​</a></h3><ul><li>Lower latency by serving from servers closer to users.</li><li>Reduce load on your origin server.</li></ul><hr><h2 id="🌐-step-3-optimize-api-requests" tabindex="-1"><span class="hub-section-number">5 </span>Optimize API Requests <a class="header-anchor" href="#🌐-step-3-optimize-api-requests" aria-label="Permalink to “5 Optimize API Requests”">​</a></h2><h3 id="_1-batch-and-aggregate-requests" tabindex="-1"><span class="hub-section-number">5.1 </span>Batch and Aggregate Requests <a class="header-anchor" href="#_1-batch-and-aggregate-requests" aria-label="Permalink to “5.1 Batch and Aggregate Requests”">​</a></h3><ul><li>Combine small API calls into one endpoint.</li><li>Example: Instead of 10 <code>/user/{id}</code> calls, use <code>/users?ids=1,2,3,…</code>.</li></ul><h3 id="_2-use-graphql-or-bff-backend-for-frontend" tabindex="-1"><span class="hub-section-number">5.2 </span>Use GraphQL or BFF (Backend-for-Frontend) <a class="header-anchor" href="#_2-use-graphql-or-bff-backend-for-frontend" aria-label="Permalink to “5.2 Use GraphQL or BFF (Backend-for-Frontend)”">​</a></h3><ul><li>A BFF can aggregate UI-specific data. GraphQL permits selection but does not automatically avoid over-fetching, N+1 work or authorization errors; enforce server budgets and data access rules.</li></ul><h3 id="_3-debounce-or-throttle-frequent-requests" tabindex="-1"><span class="hub-section-number">5.3 </span>Debounce or Throttle Frequent Requests <a class="header-anchor" href="#_3-debounce-or-throttle-frequent-requests" aria-label="Permalink to “5.3 Debounce or Throttle Frequent Requests”">​</a></h3><ul><li>Prevent flooding APIs from user input or scroll events.<div class="language-js"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> debouncedFetch</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> debounce</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(fetchData, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">300</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div></li></ul><h3 id="_4-implement-caching-layers" tabindex="-1"><span class="hub-section-number">5.4 </span>Implement Caching Layers <a class="header-anchor" href="#_4-implement-caching-layers" aria-label="Permalink to “5.4 Implement Caching Layers”">​</a></h3><ul><li>Client-side caching with React Query, SWR, or Redux Toolkit Query.</li><li>Server-side caching (Redis, CDN edge cache).</li><li>Use ETag or Last-Modified headers for conditional requests.</li></ul><h3 id="_5-lazy-load-non-critical-data" tabindex="-1"><span class="hub-section-number">5.5 </span>Lazy Load Non-Critical Data <a class="header-anchor" href="#_5-lazy-load-non-critical-data" aria-label="Permalink to “5.5 Lazy Load Non-Critical Data”">​</a></h3><ul><li>Load non-essential data after the main UI is interactive.<div class="language-js"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">useEffect</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(() </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;./analytics&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">).</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">then</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">m</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> m.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">init</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">());</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}, []);</span></span></code></pre></div></li></ul><hr><h2 id="📱-step-4-image-and-media-optimization" tabindex="-1"><span class="hub-section-number">6 </span>Image and Media Optimization <a class="header-anchor" href="#📱-step-4-image-and-media-optimization" aria-label="Permalink to “6 Image and Media Optimization”">​</a></h2><h3 id="_1-use-responsive-images" tabindex="-1"><span class="hub-section-number">6.1 </span>Use Responsive Images <a class="header-anchor" href="#_1-use-responsive-images" aria-label="Permalink to “6.1 Use Responsive Images”">​</a></h3><ul><li>Use HTML:<div class="language-html"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">img</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> srcset</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;...&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> sizes</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;...&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> src</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;...&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> alt</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;...&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /&gt;</span></span></code></pre></div></li><li>Or use Next.js <code>&lt;Image&gt;</code> to serve the right size for each device.</li></ul><h3 id="_2-lazy-loading" tabindex="-1"><span class="hub-section-number">6.2 </span>Lazy Loading <a class="header-anchor" href="#_2-lazy-loading" aria-label="Permalink to “6.2 Lazy Loading”">​</a></h3><ul><li>Use <code>loading=&quot;lazy&quot;</code> to defer off-screen image requests.</li></ul><h3 id="_3-choose-icon-delivery-deliberately" tabindex="-1"><span class="hub-section-number">6.3 </span>Choose Icon Delivery Deliberately <a class="header-anchor" href="#_3-choose-icon-delivery-deliberately" aria-label="Permalink to “6.3 Choose Icon Delivery Deliberately”">​</a></h3><ul><li>SVG sprites or a small icon subset can share bytes; inline SVG avoids a request but enlarges HTML. Icon fonts have loading/semantics trade-offs. Label meaningful controls and hide decorative icons appropriately.</li></ul><hr><h2 id="⚙️-step-5-architectural-strategies" tabindex="-1"><span class="hub-section-number">7 </span>Architectural Strategies <a class="header-anchor" href="#⚙️-step-5-architectural-strategies" aria-label="Permalink to “7 Architectural Strategies”">​</a></h2><table tabindex="0"><thead><tr><th>Technique</th><th>Description</th></tr></thead><tbody><tr><td>HTTP/2 or HTTP/3</td><td>Multiplexes — multiple requests per connection.</td></tr><tr><td>Domain Sharding</td><td>Used for HTTP/1.1 to parallelize requests (not needed for HTTP/2).</td></tr><tr><td>Service Workers</td><td>Cache assets &amp; responses offline; avoid redundant network hits.</td></tr><tr><td>Edge Functions</td><td>Pre-render and serve from CDN edge locations.</td></tr></tbody></table><hr><h2 id="✅-summary" tabindex="-1"><span class="hub-section-number">8 </span>Summary <a class="header-anchor" href="#✅-summary" aria-label="Permalink to “8 Summary”">​</a></h2><table tabindex="0"><thead><tr><th>Problem</th><th>Solution</th></tr></thead><tbody><tr><td>Too many JS/CSS files</td><td>Bundle + minify + tree shake</td></tr><tr><td>Too many API calls</td><td>Batch or aggregate calls</td></tr><tr><td>Duplicate requests</td><td>Cache at client/server/CDN</td></tr><tr><td>Unnecessary early requests</td><td>Lazy load, prefetch smartly</td></tr><tr><td>Network overhead</td><td>HTTP/2 + CDN + compression</td></tr></tbody></table><hr><h2 id="🧠-rule-of-thumb" tabindex="-1"><span class="hub-section-number">9 </span>Rule of Thumb <a class="header-anchor" href="#🧠-rule-of-thumb" aria-label="Permalink to “9 Rule of Thumb”">​</a></h2><p>Set route/device-specific budgets from a baseline and user outcomes;100requests/2MB is not a universal target. Prioritize critical-path bytes, dependency waterfalls, duplication and server cost rather than request count alone.</p><hr><h2 id="🧾-example-summary-workflow" tabindex="-1"><span class="hub-section-number">10 </span>Example Summary Workflow <a class="header-anchor" href="#🧾-example-summary-workflow" aria-label="Permalink to “10 Example Summary Workflow”">​</a></h2><ol><li>Measure with Lighthouse or DevTools.</li><li>Find redundant or late-loaded assets.</li><li>Group and bundle JS/CSS.</li><li>Defer/lazy load non-critical modules.</li><li>Cache according to freshness/privacy and invalidation requirements (client, CDN, server).</li><li>Monitor continuously (Lighthouse CI, Sentry Performance, Datadog RUM).</li></ol><h2 id="request-topology-and-failure-contract" tabindex="-1"><span class="hub-section-number">11 </span>Request topology and failure contract <a class="header-anchor" href="#request-topology-and-failure-contract" aria-label="Permalink to “11 Request topology and failure contract”">​</a></h2><p>HTTP/2 multiplexes over TCP, so packet loss can stall multiple streams at the transport layer. HTTP/3 uses QUIC streams and avoids that same cross-stream transport head-of-line blocking, but still shares congestion/bandwidth and server constraints. More concurrency is not unlimited throughput. Domain sharding can add DNS/TLS cost and lose reuse; measure rather than carrying an HTTP/1.1 workaround into a multiplexed deployment.</p><p>A batch endpoint reduces round trips but needs maximum IDs/body size, per-item authorization, predictable partial-failure semantics and a deadline. It can delay every result behind the slowest dependency. Parallel independent requests can expose useful data sooner; dependent requests create waterfalls. A GraphQL/BFF choice changes server ownership and observability, not physics.</p><p>For client query caches, define keys including all data-affecting inputs/user scope, stale policy, invalidation and bounded retention. Deduplicate in-flight equivalent reads where appropriate; abort obsolete searches and reject stale responses. Debounce alone does not cancel an already running request. Retry only classified transient failures with bounded backoff and safe/idempotent semantics; request reduction must not leak one user&#39;s private cached data to another.</p><p>References checked2026-10-20: <a href="https://www.rfc-editor.org/rfc/rfc9113.html" target="_blank" rel="noreferrer">HTTP/2</a>, <a href="https://www.rfc-editor.org/rfc/rfc9114.html" target="_blank" rel="noreferrer">HTTP/3</a>, <a href="https://www.rfc-editor.org/rfc/rfc9111.html" target="_blank" rel="noreferrer">HTTP caching</a>, <a href="https://developer.chrome.com/docs/devtools/network/reference" target="_blank" rel="noreferrer">Network tooling</a>.</p><h2 id="separate-practice" tabindex="-1"><span class="hub-section-number">12 </span>Separate practice <a class="header-anchor" href="#separate-practice" aria-label="Permalink to “12 Separate practice”">​</a></h2><p>Use the <a href="./../../practice/engineering/performance/What_if_we_are_facing_performance_issues_because_we_have_lots_of_requests.html">focused acceptance and evidence requirements</a>. All learner practice remains outstanding.</p>`,63)])])}const k=s(r,[["render",n]]);export{u as __pageData,k as default};
